package com.gerenciadorrural.modules.farms.infrastructure;
import com.gerenciadorrural.modules.farms.domain.*; import com.gerenciadorrural.shared.tenancy.TenantId; import org.springframework.dao.IncorrectResultSizeDataAccessException; import org.springframework.jdbc.core.namedparam.*; import org.springframework.stereotype.Repository; import java.util.*;
@Repository public class JdbcFarmProfileQueryRepository implements FarmProfileQueryRepository {private final NamedParameterJdbcTemplate jdbc;public JdbcFarmProfileQueryRepository(NamedParameterJdbcTemplate jdbc){this.jdbc=jdbc;}public Optional<FarmProfile> findCurrent(TenantId tenantId,UUID farmId){var rows=jdbc.query("select f.id, f.tenant_id, f.name, f.status from app.farms f where f.id=:farmId and f.tenant_id=:tenantId and f.status='ACTIVE'",new MapSqlParameterSource().addValue("farmId",farmId).addValue("tenantId",tenantId.value()),(r,n)->new FarmProfile(r.getObject("id",UUID.class),new TenantId(r.getObject("tenant_id",UUID.class)),r.getString("name"),r.getString("status")));if(rows.size()>1)throw new IncorrectResultSizeDataAccessException(1,rows.size());return rows.stream().findFirst();}}
